mapper.select:
select PROD_ID id, PROD_NAME text from V_REP_PROD_INFO where 1=1 and V_REP_PROD_INFO.rep_prod_type in ('01','02')
and STATUS=#{dataStatus,jdbcType=VARCHAR}
and (PROD_ID like concat(concat('%',#{search}),'%') or PROD_NAME like concat(concat('%',#{search}),'%'))
and PROD_ID = #{initValue}

select DNDC.NOSTD_ASSET_ID nostdAssetId, DNDC.PROD_ID prodId, RPI.PROD_NAME prodName, DNDC.EFF_DATE effDate, DNDC.EFF_END_DATE effEndDate, DNDC.FINANCIER financier, DNDC.PROJECT_NO projectNo, DNDC.PROJECT_NAME projectName, DNDC.REM_FINANCING_PERIOD remFinancingPeriod, DNDC.INCOME_DISTRIBUTE incomeDistribute, DNDC.TRD_CONSTRUCT trdConstruct, DNDC.RISK_INFO riskInfo, DNDC.DATA_STATUS dataStatus, DNDC.DATA_SOURCE dataSource, DNDC.UPDATE_TIME updateTime, DNDC.UPDATE_USER updateUser FROM DIS_NOSTD_CREDITOR DNDC LEFT JOIN V_REP_PROD_INFO RPI on DNDC.PROD_ID = RPI.PROD_ID
AND DNDC.PROD_ID = #{prodId,jdbcType=VARCHAR}
AND DNDC.EFF_DATE = TO_DATE(#{effDate,jdbcType=DATE},'YYYY-MM-DD')
AND DNDC.EFF_END_DATE = TO_DATE(#{effEndDate,jdbcType=DATE},'YYYY-MM-DD')
AND DNDC.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}
ORDER BY DNDC.PROJECT_NO

select NOSTD_ASSET_ID nostdAssetId, PROD_ID prodId, EFF_DATE effDate, EFF_END_DATE effEndDate, FINANCIER financier, PROJECT_NO projectNo, PROJECT_NAME projectName, REM_FINANCING_PERIOD remFinancingPeriod, INCOME_DISTRIBUTE incomeDistribute, TRD_CONSTRUCT trdConstruct, RISK_INFO riskInfo from DIS_NOSTD_CREDITOR
AND PROD_ID=#{prodId,jdbcType=VARCHAR}
AND DATA_STATUS=#{status,jdbcType=VARCHAR}
AND EFF_END_DATE != to_date(#{effEndDateO,jdbcType=VARCHAR},'yyyy-MM-dd')
AND EFF_DATE != to_date(#{effDateO,jdbcType=VARCHAR},'yyyy-MM-dd')

select count(*) from DIS_NOSTD_CREDITOR DNDC


         AND DNDC.PROD_ID = #{prodId,jdbcType=VARCHAR}


         AND DNDC.EFF_DATE = TO_DATE(#{effDate,jdbcType=DATE},'YYYY-MM-DD')


         AND DNDC.EFF_END_DATE = TO_DATE(#{effEndDate,jdbcType=DATE},'YYYY-MM-DD')


         AND DNDC.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}

SELECT PROD_ID id, PROD_ID text, PROD_RE object FROM V_REP_PROD_INFO
AND PROD_RE=#{prodRegistNo}
and (PROD_ID like concat(concat('%',#{search}),'%') or PROD_NAME like concat(concat('%',#{search}),'%'))

mapper.delete:
update DIS_NOSTD_CREDITOR DNDC set DATA_STATUS = 'D'


        AND DNDC.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}


        AND  DNDC.EFF_DATE >= TO_DATE(#{effDate},'YYYY-MM-DD') 


        AND  DNDC.EFF_END_DATE <= TO_DATE(#{effEndDate},'YYYY-MM-DD')


        AND DNDC.PROD_ID = #{prodId,jdbcType=VARCHAR}

delete from DIS_NOSTD_CREDITOR DNDC


        AND DNDC.DATA_STATUS = #{dataStatus,jdbcType=VARCHAR}


        AND  DNDC.EFF_DATE = TO_DATE(#{effDateOStr},'YYYY-MM-DD')


        AND  DNDC.EFF_END_DATE = TO_DATE(#{effEndDateOStr},'YYYY-MM-DD')


        AND DNDC.PROD_ID = #{prodId,jdbcType=VARCHAR}

mapper.insert:
insert into DIS_NOSTD_CREDITOR(NOSTD_ASSET_ID,PROD_ID,EFF_DATE,EFF_END_DATE,FINANCIER, PROJECT_NO, PROJECT_NAME,REM_FINANCING_PERIOD,INCOME_DISTRIBUTE, TRD_CONSTRUCT,RISK_INFO ,DATA_STATUS, DATA_SOURCE,CREATE_USER ,CREATE_TIME,UPDATE_USER, UPDATE_TIME,CREATE_DEPT) select A.* from (
select #{item.nostdAssetID,jdbcType=VARCHAR} NOSTD_ASSET_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.effDate,jdbcType=DATE} EFF_DATE, #{item.effEndDate,jdbcType=DATE} EFF_END_DATE, #{item.dataStatus,jdbcType=VARCHAR} FINANCIER, #{item.projectNo,jdbcType=VARCHAR} PROJECT_NO, #{item.projectName,jdbcType=VARCHAR} PROJECT_NAME, #{item.remFinancingPeriod,jdbcType=VARCHAR} REM_FINANCING_PERIOD, #{item.incomeDistribute,jdbcType=VARCHAR} INCOME_DISTRIBUTE, #{item.trdConstruct,jdbcType=VARCHAR} TRD_CONSTRUCT, #{item.riskInfo,jdbcType=VARCHAR} RISK_INFO, #{item.dataStatus,jdbcType=VARCHAR} DATA_STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT from dual
)A

